{
  "headline": "FDA's records trace our supply to a plant classified OAI 894 days before the shortage posting",
  "headline_cites": ["D4"],
  "sentences": [
    {
      "text": "FDA first posted the sufentanil citrate shortage on 2022-05-03 and it remains current as of 2026-10-21, spanning 54 months.",
      "cites": ["E19", "D7"]
    },
    {
      "text": "The product used at Corvale East and Corvale General carries NDC 00409338221 labeled by Hospira, Inc., and the SPL set ID 20293943 identifies the same labeler and plant.",
      "cites": ["E1", "E2", "E16"]
    },
    {
      "text": "FDA inspection 1110899 at that plant ended 2019-11-21 and was classified VAI, with the classification letter dated 2020-02-12 — 894 days before the shortage posting.",
      "cites": ["D4", "E14"]
    },
    {
      "text": "Earlier inspections at the same plant include OAI classifications on 2010-01-19, 2011-06-17, and 2011-08-04, and a Warning Letter on 2010-04-12.",
      "cites": ["E6", "E8", "E10", "E15"]
    },
    {
      "text": "The most recent inspection on record ended 2025-02-07 and was classified NAI.",
      "cites": ["E16"]
    },
    {
      "text": "Corvale East has 7 days on hand, Corvale Lakeside has 21 days on hand, and the rule‑ranked option is to transfer 17 units from Corvale Lakeside to Corvale East, which would raise East to 9 days on hand while Lakeside retains two weeks.",
      "cites": ["D1", "D3", "D5"]
    }
  ]
}
